head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil00101";
scwin.formMandtryTpCd = null;
scwin.formCdVal = null;
scwin.formVerVal = null;
scwin.wrtrptMaindocTpCd = null;

// TODO Stage2: 세션 키 실환경 확인(회신 11항 · user-info 계약에 없는 키) — session.user.usrTpCd

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_fillGen();
        scwin.init_rowCopy();
        scwin.init_conds();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil00101.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_usrTpCd", fn: function(){ return ($c.session.getUserInfo("usrTpCd") === '3'); } }, { id: "c_when_99_txt", fn: function(){ return ((dlt_result.getCellData(0, "formMandtryTpCd") ?? (() => { throw new Error("unresolved:" + "result.formMandtryTpCd"); })()) === '0'); } }, { id: "c_when_100_txt", fn: function(){ return ((dlt_result.getCellData(0, "formMandtryTpCd") ?? (() => { throw new Error("unresolved:" + "result.formMandtryTpCd"); })()) === '1'); } }, { id: "c_when_101_txt", fn: function(){ return ((dlt_result.getCellData(0, "formMandtryTpCd") ?? (() => { throw new Error("unresolved:" + "result.formMandtryTpCd"); })()) === '2'); } }, { id: "c_when_102_txt", fn: function(){ return ((dlt_result.getCellData(0, "formMandtryTpCd") ?? (() => { throw new Error("unresolved:" + "result.formMandtryTpCd"); })()) === '3'); } }, { id: "c_when_106_txt", fn: function(){ return ((dlt_result.getCellData(0, "disclsAcptTpCd") ?? (() => { throw new Error("unresolved:" + "result.disclsAcptTpCd"); })()) === 'M'); } }, { id: "c_when_107_txt", fn: function(){ return ((dlt_result.getCellData(0, "disclsAcptTpCd") ?? (() => { throw new Error("unresolved:" + "result.disclsAcptTpCd"); })()) === 'A'); } }, { id: "if_langTpCd", fn: function(){ return ((dma_disclosureVo.get("langTpCd") ?? (() => { throw new Error("unresolved:" + "disclosureVo.langTpCd"); })()) === '0'); } }, { id: "c_when_111_txt", fn: function(){ return ((dlt_result.getCellData(0, "disclsAcptTpCd") ?? (() => { throw new Error("unresolved:" + "result.disclsAcptTpCd"); })()) === 'M'); } }, { id: "c_when_112_txt", fn: function(){ return ((dlt_result.getCellData(0, "disclsAcptTpCd") ?? (() => { throw new Error("unresolved:" + "result.disclsAcptTpCd"); })()) === 'A'); } }, { id: "if_langTpCd_2", fn: function(){ return ((dma_disclosureVo.get("langTpCd") ?? (() => { throw new Error("unresolved:" + "disclosureVo.langTpCd"); })()) === '1'); } }, { id: "c_when_118_txt", fn: function(){ return ((dlt_result.getCellData(0, "formMandtryTpCd") ?? (() => { throw new Error("unresolved:" + "result.formMandtryTpCd"); })()) === '0'); } }, { id: "c_when_119_txt", fn: function(){ return ((dlt_result.getCellData(0, "formMandtryTpCd") ?? (() => { throw new Error("unresolved:" + "result.formMandtryTpCd"); })()) === '1'); } }, { id: "c_when_120_txt", fn: function(){ return ((dlt_result.getCellData(0, "formMandtryTpCd") ?? (() => { throw new Error("unresolved:" + "result.formMandtryTpCd"); })()) === '2'); } }, { id: "c_when_121_txt", fn: function(){ return ((dlt_result.getCellData(0, "formMandtryTpCd") ?? (() => { throw new Error("unresolved:" + "result.formMandtryTpCd"); })()) === '3'); } }, { id: "if_wrtYn", fn: function(){ return ((dlt_result.getCellData(0, "wrtYn") ?? (() => { throw new Error("unresolved:" + "result.wrtYn"); })()) === 'N'); } }, { id: "ipt_revTgtList", fn: function(){ return ((dlt_result.getCellData(0, "formMandtryTpCd") ?? (() => { throw new Error("unresolved:" + "result.formMandtryTpCd"); })()) === '0'); } }, { id: "ipt_revTgtList_2", fn: function(){ return ((dlt_result.getCellData(0, "formMandtryTpCd") ?? (() => { throw new Error("unresolved:" + "result.formMandtryTpCd"); })()) === '1'); } }, { id: "ipt_revTgtList_3", fn: function(){ return ((dlt_result.getCellData(0, "formMandtryTpCd") ?? (() => { throw new Error("unresolved:" + "result.formMandtryTpCd"); })()) === '2'); } }, { id: "ipt_revTgtList_4", fn: function(){ return ((dlt_result.getCellData(0, "formMandtryTpCd") ?? (() => { throw new Error("unresolved:" + "result.formMandtryTpCd"); })()) === '3'); } }, { id: "if_wrtYn_2", fn: function(){ return ((dlt_result.getCellData(0, "wrtYn") ?? (() => { throw new Error("unresolved:" + "result.wrtYn"); })()) === 'Y'); } }, { id: "ipt_revTgtList_5", fn: function(){ return ((dlt_result.getCellData(0, "formMandtryTpCd") ?? (() => { throw new Error("unresolved:" + "result.formMandtryTpCd"); })()) === '0'); } }, { id: "ipt_revTgtList_6", fn: function(){ return ((dlt_result.getCellData(0, "formMandtryTpCd") ?? (() => { throw new Error("unresolved:" + "result.formMandtryTpCd"); })()) === '2'); } }, { id: "if_wrtYn_3", fn: function(){ return ((dlt_result.getCellData(0, "wrtYn") ?? (() => { throw new Error("unresolved:" + "result.wrtYn"); })()) === 'N'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_95", entity: "dlt_result", countIds: [], cells: [{ childId: "__rc0", fn: function (v, i) { return String(v("formKorNm")); } }, { childId: "__rc1", fn: function (v, i) { return "(영문)" + String(v("formKorNm")); } }, { childId: "ipt_revTgtList", fn: function (v, i) { return String(v("formMandtryTpCd")) + "," + String(v("acptNo")) + "," + String(v("docNo")) + "," + String(v("oldFormCd")) + "," + String(v("oldFormVer")) + "," + String(v("formCd")) + "," + String(v("formVer")) + "," + String(v("wrtrptMaindocTpCd")); } }, { childId: "ipt_revTgtList_2", fn: function (v, i) { return String(v("formMandtryTpCd")) + "," + String(v("acptNo")) + "," + String(v("docNo")) + "," + String(v("oldFormCd")) + "," + String(v("oldFormVer")) + "," + String(v("formCd")) + "," + String(v("formVer")) + "," + String(v("wrtrptMaindocTpCd")); } }, { childId: "ipt_revTgtList_3", fn: function (v, i) { return String(v("formMandtryTpCd")) + "," + String(v("acptNo")) + "," + String(v("docNo")) + "," + String(v("oldFormCd")) + "," + String(v("oldFormVer")) + "," + String(v("formCd")) + "," + String(v("formVer")) + "," + String(v("wrtrptMaindocTpCd")); } }, { childId: "ipt_revTgtList_4", fn: function (v, i) { return String(v("formMandtryTpCd")) + "," + String(v("acptNo")) + "," + String(v("docNo")) + "," + String(v("oldFormCd")) + "," + String(v("oldFormVer")) + "," + String(v("formCd")) + "," + String(v("formVer")) + "," + String(v("wrtrptMaindocTpCd")); } }, { childId: "ipt_revTgtList_5", fn: function (v, i) { return String(v("formMandtryTpCd")) + "," + String(v("acptNo")) + "," + String(v("docNo")) + "," + String(v("oldFormCd")) + "," + String(v("oldFormVer")) + "," + String(v("formCd")) + "," + String(v("formVer")) + "," + String(v("wrtrptMaindocTpCd")); } }, { childId: "ipt_revTgtList_6", fn: function (v, i) { return String(v("formMandtryTpCd")) + "," + String(v("acptNo")) + "," + String(v("docNo")) + "," + String(v("oldFormCd")) + "," + String(v("oldFormVer")) + "," + String(v("formCd")) + "," + String(v("formVer")) + "," + String(v("wrtrptMaindocTpCd")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_prevMenuId", fn: function () { return String((dma_pageContext.get("prevMenuId") ?? "")); } },
        { childId: "ipt_method", fn: function () { return String((dma_pageContext.get("method") ?? "")); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_goWrite();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
