///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_tempRegister_go
 * @description temp Register go 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_tempRegister_go = async function (action) {
    const sbmOptions = {
        id: "tx_fn_tempRegister_go",
        method: "post",
        action: action ?? "/submission/disclosurereg.do?method=registerAmendDisclosure",
        ref: "dma_tempRegisterGoReq",
        target: "dlt_result=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_tempRegister
 * @description temp Register 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_tempRegister = async function (action) {
    const sbmOptions = {
        id: "tx_fn_tempRegister",
        method: "post",
        action: action ?? "/submission/disclosurereg.do?method=registerDisclosure",
        ref: "dma_tempRegisterReq",
        target: "dlt_result=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_goWrite
 * @description go Write 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_goWrite = async function (action) {
    const sbmOptions = {
        id: "tx_fn_goWrite",
        method: "post",
        action: action ?? "/submission/disclosure.do?method=searchDisclosureDocument",
        ref: "dma_goWriteReq",
        target: "dlt_result=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name essential_chk
 * @description essential chk 처리
 * @param {*} num num
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.essential_chk = async function (num) {
    with ((document.searchForm || { elements: [] })) {
        const len = revTgtList.length;
        if (num === 0) {
            for (let i = 0; i < len; i++) {
                if (revTgtList[i].checked && revTgtList[i].value.split(",")[0] === '0') {
