                        if ((scwin.formMandtryTpCd === '2' || scwin.formMandtryTpCd === '3') && (revTgtList[i].value.split(",")[0] !== '2' || revTgtList[i].value.split(",")[0] !== '3') && revTgtList[i].value.split(",")[0] === '0' && disclsMaindocFormCd.value !== '99602' && disclsMaindocFormCd.value !== '99603') {
                            await $c.win.alert("본문문서와 첨부문서 중 첨부필수문서는 \n함께 정정되어야 합니다.\n본문과 첨부필수문서가 함께 선택됩니다.");
                            revTgtList[i].checked = true;
                            revTgtList[a].checked = true;
                        }
                    }
                } else {
                    if (!revTgtList[i].checked && revTgtList[i].value.split(",")[0] === '0') {
                        for (let a = 0; a < len; a++) {
                            arry = revTgtList[a].value.split(",");
                            scwin.formMandtryTpCd = arry[0];
                            if ((scwin.formMandtryTpCd === '2' || scwin.formMandtryTpCd === '3') && revTgtList[a].value !== revTgtList[i].value) {
                                revTgtList[i].checked = false;
                                revTgtList[a].checked = false;
                            }
                        }
                    }
                }
            }
        } else {
            if (num === 2) {
                for (let i = 0; i < len; i++) {
                    if (revTgtList[i].checked && (revTgtList[i].value.split(",")[0] === '2' || revTgtList[i].value.split(",")[0] === '3')) {
                        for (let a = 0; a < len; a++) {
                            arry = revTgtList[a].value.split(",");
                            scwin.formMandtryTpCd = arry[0];
                            if (scwin.formMandtryTpCd === '0' && disclsMaindocFormCd.value !== '99602' && disclsMaindocFormCd.value !== '99603') {
                                await $c.win.alert("본문문서와 첨부문서 중 첨부필수문서는 \n함께 정정되어야 합니다.\n본문과 첨부필수문서가 함께 선택됩니다.");
                                revTgtList[i].checked = true;
                                revTgtList[a].checked = true;
                            }
                        }
                    } else {
                        if (!revTgtList[i].checked && (revTgtList[i].value.split(",")[0] === '2' || revTgtList[i].value.split(",")[0] === '3')) {
                            for (let a = 0; a < len; a++) {
                                arry = revTgtList[a].value.split(",");
                                scwin.formMandtryTpCd = arry[0];
                                if (scwin.formMandtryTpCd === '0') {
                                    revTgtList[i].checked = false;
                                    revTgtList[a].checked = false;
                                }
                            }
                        }
                    }
                }
            } else {
                if (num === 3) {
                    for (let i = 0; i < len; i++) {
                        if (revTgtList[i].checked && (revTgtList[i].value.split(",")[0] === '2' || revTgtList[i].value.split(",")[0] === '3')) {
                            for (let a = 0; a < len; a++) {
                                arry = revTgtList[a].value.split(",");
                                scwin.formMandtryTpCd = arry[0];
                                if (scwin.formMandtryTpCd === '0' && disclsMaindocFormCd.value !== '99602' && disclsMaindocFormCd.value !== '99603') {
                                    await $c.win.alert("본문문서와 첨부문서 중 첨부필수문서는 \n함께 정정되어야 합니다.\n본문과 첨부필수문서가 함께 선택됩니다.");
                                    revTgtList[i].checked = true;
                                    revTgtList[a].checked = true;
                                }
                            }
                        } else {
                            if (!revTgtList[i].checked && (revTgtList[i].value.split(",")[0] === '2' || revTgtList[i].value.split(",")[0] === '3')) {
                                for (let a = 0; a < len; a++) {
