                    }
                }
            }
        }
    }
};

/**
 * @method
 * @name tempRegisterGo
 * @description temp Register Go 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tempRegisterGo = async function () {
    let isCheckedVal = false;
    with ((document.searchForm || { elements: [] })) {
        const len = revTgtList.length;
        if (len == null || len === 1) {
            if (revTgtList.checked) {
                isCheckedVal = true;
            }
            let arry = revTgtList.value.split(",");
            scwin.formMandtryTpCd = arry[0];
            scwin.formCdVal = arry[5];
            scwin.formVerVal = arry[6];
            scwin.wrtrptMaindocTpCd = arry[7];
            if (scwin.formMandtryTpCd === '0') {
                formCd.value = scwin.formCdVal;
                formVer.value = scwin.formVerVal;
                $c.util.getComponent('dma_tempRegisterGoReq').set('formCd', scwin.formCdVal);
                $c.util.getComponent('dma_tempRegisterGoReq').set('formVer', scwin.formVerVal);
            } else {
                formCd.value = scwin.formCdVal;
                formVer.value = scwin.formVerVal;
                $c.util.getComponent('dma_tempRegisterGoReq').set('formCd', scwin.formCdVal);
                $c.util.getComponent('dma_tempRegisterGoReq').set('formVer', scwin.formVerVal);
            }
            if (scwin.wrtrptMaindocTpCd === '2') {
                $c.util.getComponent('dma_tempRegisterGoReq').set('disclsAcptTpCd', 'U');
                $c.util.getComponent('dma_tempRegisterGoReq').set('disclsAcptTpCd', 'U');
                $c.util.getComponent('dma_tempRegisterGoReq').set('wrtrptMaindocTpCd', '2');
            } else {
                $c.util.getComponent('dma_tempRegisterGoReq').set('disclsAcptTpCd', 'M');
                $c.util.getComponent('dma_tempRegisterGoReq').set('disclsAcptTpCd', 'M');
                $c.util.getComponent('dma_tempRegisterGoReq').set('wrtrptMaindocTpCd', '1');
            }
        } else {
            for (let i = 0; i < len; i++) {
                if (revTgtList[i].checked) {
                    isCheckedVal = true;
                    break;
                }
            }
            let isModifyUYn = true;
            for (let i = 0; i < len; i++) {
                arry = revTgtList[i].value.split(",");
                scwin.formMandtryTpCd = arry[0];
                scwin.formCdVal = arry[5];
                scwin.formVerVal = arry[6];
                scwin.wrtrptMaindocTpCd = arry[7];
                if (scwin.wrtrptMaindocTpCd === '1' && revTgtList[i].checked) {
                    isModifyUYn = false;
                    break;
                }
            }
            if (isModifyUYn) {
                for (let i = 0; i < len; i++) {
                    arry = revTgtList[i].value.split(",");
                    scwin.formMandtryTpCd = arry[0];
                    scwin.formCdVal = arry[5];
                    scwin.formVerVal = arry[6];
                    scwin.wrtrptMaindocTpCd = arry[7];
                    if ((scwin.formMandtryTpCd === '1' || scwin.formMandtryTpCd === '2' || scwin.formMandtryTpCd === '3') && revTgtList[i].checked) {
                        formCd.value = scwin.formCdVal;
                        formVer.value = scwin.formVerVal;
                        $c.util.getComponent('dma_tempRegisterGoReq').set('formCd', scwin.formCdVal);
                        $c.util.getComponent('dma_tempRegisterGoReq').set('formVer', scwin.formVerVal);
                        break;
                    }
                }
            } else {
                formCd.value = disclsMaindocFormCd.value;
                formVer.value = disclsMaindocFormVer.value;
                $c.util.getComponent('dma_tempRegisterGoReq').set('formCd', disclsMaindocFormCd.value);
                $c.util.getComponent('dma_tempRegisterGoReq').set('formVer', disclsMaindocFormVer.value);
            }
            if (isModifyUYn) {
                $c.util.getComponent('dma_tempRegisterGoReq').set('disclsAcptTpCd', 'U');
                $c.util.getComponent('dma_tempRegisterGoReq').set('disclsAcptTpCd', 'U');
                $c.util.getComponent('dma_tempRegisterGoReq').set('wrtrptMaindocTpCd', '2');
            } else {
                $c.util.getComponent('dma_tempRegisterGoReq').set('disclsAcptTpCd', 'M');
                $c.util.getComponent('dma_tempRegisterGoReq').set('disclsAcptTpCd', 'M');
                $c.util.getComponent('dma_tempRegisterGoReq').set('wrtrptMaindocTpCd', '1');
            }
        }
    }
    if (!isCheckedVal) {
        await $c.win.alert('정정하실 문서를 선택하십시요');
        return;
    }
    $c.util.getComponent('dma_tempRegisterGoReq').set('exmptObjDisclsYn', '' + dma_disclosureVo.get("exmptObjDisclsYn") + '');
    await scwin.tx_fn_tempRegister_go('/submission/disclosurereg.do?method=registerAmendDisclosure');
};

/**
 * @method
 * @name tempRegister
 * @description temp Register 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tempRegister = async function () {
    if ('FIL00330' === $c.util.getComponent('ipt_prevMenuId').getValue()) {
        await $c.win.alert($c.util.getComponent('ipt_prevMenuId').getValue());
        await scwin.tx_fn_tempRegister('/submission/disclosurereg.do?method=registerDisclosure');
    } else {
        await scwin.tempRegisterGo();
    }
};

